// ─── File: AutocompleteDemo.java ───
// Runnable demo. Each class would be its own file in a real project.
package com.bank.autocomplete;

import java.util.*;
import java.util.logging.*;

public class AutocompleteDemo {
    private static final Logger log = Logger.getLogger(AutocompleteDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Trie trie = new Trie(5);  // top-5 per node
        // Insert phrases with popularity scores (from historical query logs)
        trie.insert("home loan", 950);
        trie.insert("home insurance", 600);
        trie.insert("housing scheme", 300);
        trie.insert("home loan top-up", 200);
        trie.insert("loan against property", 700);
        trie.insert("loan calculator", 500);
        trie.insert("fixed deposit", 800);

        SuggestionService service = new SuggestionService(trie, 60);

        // Query "ho" — pre-ranked top-K read, measured latency
        log.info("Suggestions for 'ho' (first call, from trie):");
        service.suggest("ho").forEach(s -> log.info("  " + s));

        // Query "ho" again — served from hot-prefix cache
        log.info("Suggestions for 'ho' (second call, from cache):");
        service.suggest("ho").forEach(s -> log.info("  " + s));

        // Query "lo" — ranked by popularity
        log.info("Suggestions for 'lo':");
        service.suggest("lo").forEach(s -> log.info("  " + s));

        // Client-side debounce: 'h','o','m','e' typed quickly → ONE request for "home"
        Debouncer debouncer = new Debouncer(200);
        for (char c : "home".toCharArray()) debouncer.onKeystroke("" + c);
        String fired = debouncer.flush();   // simulate the pause after typing
        log.info("Debounced keystrokes h,o,m,e → single request for prefix: '" + fired + "'");
        service.suggest(fired).forEach(s -> log.info("  " + s));
    }
}

// ─── model/Suggestion.java ───
class Suggestion {
    final String phrase; final int score;
        Suggestion(String phrase, int score) { this.phrase = phrase;
        this.score = score; }
    @Override public String toString() { return "\"" + phrase + "\" (score=" + score + ")"; }
}

// ─── trie/TrieNode.java ───
class TrieNode {
    final Map<Character, TrieNode> children = new HashMap<>();
    // Pre-ranked top-K completions passing through this node (pinned at insert time).
    final List<Suggestion> topK = new ArrayList<>();
}

// ─── trie/Trie.java ───
// Prefix tree. Each node keeps a pre-ranked top-K so a query is just a read.
class Trie {
    private final TrieNode root = new TrieNode();
    private final int k;
    Trie(int k) { this.k = k; }

    void insert(String phrase, int score) {
        Suggestion s = new Suggestion(phrase, score);
        TrieNode node = root;
        mergeTopK(node, s);                           // root holds global top-K too
        for (char c : phrase.toCharArray()) {
            node = node.children.computeIfAbsent(c, x -> new TrieNode());
            mergeTopK(node, s);                        // every prefix node gets this phrase considered
        }
    }
    // Keep only the top-K by score at this node (precomputed ranking).
    private void mergeTopK(TrieNode node, Suggestion s) {
        node.topK.removeIf(x -> x.phrase.equals(s.phrase));
        node.topK.add(s);
        node.topK.sort((a, b) -> b.score - a.score);
        while (node.topK.size() > k) node.topK.remove(node.topK.size() - 1);
    }

    List<Suggestion> suggest(String prefix) {
        TrieNode node = root;
        for (char c : prefix.toCharArray()) {
            node = node.children.get(c);
            if (node == null) return List.of();       // no phrase with this prefix
        }
        return new ArrayList<>(node.topK);            // O(K) read — no sorting at query time
    }
}

// ─── service/PrefixCache.java ───
// Caches pre-ranked lists for hot prefixes with a TTL.
class PrefixCache {
    private static class Entry { final List<Suggestion> list; final long expireAt;
        Entry(List<Suggestion> l, long e) { list = l; expireAt = e; } }
    private final Map<String, Entry> cache = new HashMap<>();
    private final long ttlMs;
    PrefixCache(long ttlSeconds) { this.ttlMs = ttlSeconds * 1000; }
    List<Suggestion> get(String prefix) {
        Entry e = cache.get(prefix);
        if (e != null && e.expireAt > System.currentTimeMillis()) return e.list;
        return null;
    }
    void put(String prefix, List<Suggestion> list) {
        cache.put(prefix, new Entry(list, System.currentTimeMillis() + ttlMs));
    }
}

// ─── service/SuggestionService.java ───
// Cache-first, then trie. Measures and logs latency against the budget.
class SuggestionService {
    private static final Logger log = Logger.getLogger(SuggestionService.class.getName());
    private final Trie trie; private final PrefixCache cache;
    SuggestionService(Trie trie, long cacheTtlSeconds) {
            this.trie = trie;
            this.cache = new PrefixCache(cacheTtlSeconds);
    }
    List<Suggestion> suggest(String prefix) {
        long start = System.nanoTime();
        List<Suggestion> cached = cache.get(prefix);
        List<Suggestion> result;
        if (cached != null) {
            result = cached;
            log.fine("CACHE HIT for '" + prefix + "'");
        } else {
            result = trie.suggest(prefix);
            cache.put(prefix, result);
            log.fine("CACHE MISS for '" + prefix + "' → from trie");
        }
        long micros = (System.nanoTime() - start) / 1000;
        log.fine(() -> "latency for '" + prefix + "' = " + micros + "µs");
        return result;
    }
}

// ─── client/Debouncer.java ───
// Simulates client-side debounce: collapses rapid keystrokes into the latest prefix.
class Debouncer {
    private final long debounceMs; private String pending = "";
    Debouncer(long debounceMs) { this.debounceMs = debounceMs; }
    void onKeystroke(String ch) { pending += ch; }   // accumulate; a real client resets a timer
        String flush() { String p = pending;
        return p; } // only AFTER debounceMs of idle → one request
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
